INSERT INTO `workouts` (`id_workout`, `name`, `category`, `difficulty`, `duration`, `calories`, `image`, `description`, `exercises`, `equipment`, `focus`, `created_at`) VALUES
(1, 'Cardio Ringan 30 Menit', 'cardio', 'beginner', 30, 180, '🏃', 'Latihan cardio ringan untuk pemula, cocok untuk hari pemulihan', '[\r\n        {\"name\": \"Jogging di Tempat\", \"duration\": \"5 menit\", \"sets\": \"1 set\"},\r\n        {\"name\": \"Jumping Jack\", \"duration\": \"3 menit\", \"sets\": \"3 set\"},\r\n        {\"name\": \"High Knees\", \"duration\": \"3 menit\", \"sets\": \"3 set\"},\r\n        {\"name\": \"Butt Kicks\", \"duration\": \"3 menit\", \"sets\": \"3 set\"},\r\n        {\"name\": \"Mountain Climber\", \"duration\": \"3 menit\", \"sets\": \"3 set\"},\r\n        {\"name\": \"Cool Down\", \"duration\": \"5 menit\", \"sets\": \"1 set\"}\r\n    ]', '[\"Matras\", \"Sepatu Olahraga\"]', '[\"Jantung\", \"Stamina\", \"Pembakaran Lemak\"]', '2025-10-22 10:29:44'),
(2, 'Full Body Strength', 'strength', 'intermediate', 45, 220, '🏋️', 'Latihan kekuatan seluruh tubuh dengan berat badan', '[\r\n        {\"name\": \"Push Up\", \"duration\": \"-\", \"sets\": \"3 set x 15 reps\"},\r\n        {\"name\": \"Squat\", \"duration\": \"-\", \"sets\": \"3 set x 20 reps\"},\r\n        {\"name\": \"Plank\", \"duration\": \"1 menit\", \"sets\": \"3 set\"},\r\n        {\"name\": \"Lunges\", \"duration\": \"-\", \"sets\": \"3 set x 12 reps/sisi\"},\r\n        {\"name\": \"Tricep Dips\", \"duration\": \"-\", \"sets\": \"3 set x 15 reps\"},\r\n        {\"name\": \"Glute Bridge\", \"duration\": \"-\", \"sets\": \"3 set x 20 reps\"}\r\n    ]', '[\"Matras\"]', '[\"Kekuatan\", \"Otot Inti\", \"Stabilitas\"]', '2025-10-22 10:29:44'),
(3, 'Yoga Flow untuk Pemula', 'yoga', 'beginner', 25, 120, '🧘', 'Sequence yoga dasar untuk meningkatkan fleksibilitas dan relaksasi', '[\r\n        {\"name\": \"Pemanasan & Breathing\", \"duration\": \"5 menit\", \"sets\": \"1 set\"},\r\n        {\"name\": \"Sun Salutation\", \"duration\": \"-\", \"sets\": \"5 repetisi\"},\r\n        {\"name\": \"Warrior Pose\", \"duration\": \"30 detik/sisi\", \"sets\": \"2 set\"},\r\n        {\"name\": \"Tree Pose\", \"duration\": \"30 detik/sisi\", \"sets\": \"2 set\"},\r\n        {\"name\": \"Child\'s Pose\", \"duration\": \"2 menit\", \"sets\": \"1 set\"},\r\n        {\"name\": \"Savasana\", \"duration\": \"5 menit\", \"sets\": \"1 set\"}\r\n    ]', '[\"Matras Yoga\", \"Blok Yoga (opsional)\"]', '[\"Fleksibilitas\", \"Relaksasi\", \"Keseimbangan\"]', '2025-10-22 10:29:44'),
(4, 'HIIT Burn Fat', 'hiit', 'intermediate', 20, 250, '⚡', 'High Intensity Interval Training untuk pembakaran lemak maksimal', '[\r\n        {\"name\": \"Burpees\", \"duration\": \"45 detik\", \"sets\": \"4 set\"},\r\n        {\"name\": \"Mountain Climbers\", \"duration\": \"45 detik\", \"sets\": \"4 set\"},\r\n        {\"name\": \"Jump Squats\", \"duration\": \"45 detik\", \"sets\": \"4 set\"},\r\n        {\"name\": \"Plank Jacks\", \"duration\": \"45 detik\", \"sets\": \"4 set\"},\r\n        {\"name\": \"High Knees\", \"duration\": \"45 detik\", \"sets\": \"4 set\"},\r\n        {\"name\": \"Rest\", \"duration\": \"15 detik\", \"sets\": \"setiap exercise\"}\r\n    ]', '[\"Matras\", \"Timer\"]', '[\"Pembakaran Lemak\", \"Stamina\", \"Kekuatan\"]', '2025-10-22 10:29:44'),
(5, 'Upper Body Sculpt', 'upperbody', 'intermediate', 35, 200, '💪', 'Latihan khusus untuk membentuk otot bagian atas tubuh', '[\r\n        {\"name\": \"Push Up Variasi\", \"duration\": \"-\", \"sets\": \"4 set x 12 reps\"},\r\n        {\"name\": \"Tricep Dips\", \"duration\": \"-\", \"sets\": \"3 set x 15 reps\"},\r\n        {\"name\": \"Plank to Push Up\", \"duration\": \"-\", \"sets\": \"3 set x 10 reps\"},\r\n        {\"name\": \"Arm Circles\", \"duration\": \"1 menit\", \"sets\": \"3 set\"},\r\n        {\"name\": \"Shoulder Taps\", \"duration\": \"-\", \"sets\": \"3 set x 20 reps\"}\r\n    ]', '[\"Matras\", \"Kursi untuk dips\"]', '[\"Dada\", \"Lengan\", \"Bahu\"]', '2025-10-22 10:29:44'),
(6, 'Lower Body Power', 'lowerbody', 'advanced', 40, 280, '🦵', 'Latihan intensif untuk kaki dan glutes', '[\r\n        {\"name\": \"Barbell Squat\", \"duration\": \"-\", \"sets\": \"4 set x 8-10 reps\"},\r\n        {\"name\": \"Deadlift\", \"duration\": \"-\", \"sets\": \"4 set x 8 reps\"},\r\n        {\"name\": \"Lunges\", \"duration\": \"-\", \"sets\": \"3 set x 12 reps/sisi\"},\r\n        {\"name\": \"Leg Press\", \"duration\": \"-\", \"sets\": \"3 set x 12 reps\"},\r\n        {\"name\": \"Calf Raises\", \"duration\": \"-\", \"sets\": \"4 set x 15 reps\"}\r\n    ]', '[\"Barbell\", \"Dumbbell\", \"Leg Press Machine\"]', '[\"Kaki\", \"Glutes\", \"Kekuatan\"]', '2025-10-22 10:29:44'),
(7, 'Core Strength Advanced', 'fullbody', 'advanced', 25, 180, '🔥', 'Latihan otot inti yang menantang untuk core yang kuat', '[\r\n        {\"name\": \"Dragon Flag\", \"duration\": \"-\", \"sets\": \"3 set x 8 reps\"},\r\n        {\"name\": \"L-Sit\", \"duration\": \"30 detik\", \"sets\": \"3 set\"},\r\n        {\"name\": \"Hanging Leg Raises\", \"duration\": \"-\", \"sets\": \"3 set x 12 reps\"},\r\n        {\"name\": \"Russian Twist\", \"duration\": \"-\", \"sets\": \"3 set x 20 reps\"},\r\n        {\"name\": \"Plank Variations\", \"duration\": \"1 menit\", \"sets\": \"3 set\"}\r\n    ]', '[\"Pull-up Bar\", \"Matras\"]', '[\"Otot Inti\", \"Kekuatan\", \"Stabilitas\"]', '2025-10-22 10:29:44'),
(8, 'Morning Energizer', 'cardio', 'beginner', 15, 100, '🌅', 'Latihan singkat untuk memulai hari dengan energi', '[\r\n        {\"name\": \"Dynamic Stretching\", \"duration\": \"3 menit\", \"sets\": \"1 set\"},\r\n        {\"name\": \"Jumping Jack\", \"duration\": \"2 menit\", \"sets\": \"2 set\"},\r\n        {\"name\": \"Arm Circles\", \"duration\": \"2 menit\", \"sets\": \"2 set\"},\r\n        {\"name\": \"Leg Swings\", \"duration\": \"2 menit\", \"sets\": \"2 set\"},\r\n        {\"name\": \"Deep Breathing\", \"duration\": \"3 menit\", \"sets\": \"1 set\"}\r\n    ]', '[\"Matras\"]', '[\"Energi\", \"Mobilitas\", \"Sirkulasi\"]', '2025-10-22 10:29:44');
